package com.st3;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SlayerTaskTimeTrackerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SlayerTaskTimeTrackerPlugin.class);
		RuneLite.main(args);
	}
}

package com.st3;

final class TaskHistoryEntry
{
	private String taskName;
	private int initialAmount;
	private long startedAtMillis;
	private long completedAtMillis;
	private long totalMillis;
	private long efficientMillis;
	private int manualResetCount;

	@SuppressWarnings("unused")
	private TaskHistoryEntry()
	{
	}

	TaskHistoryEntry(ActiveSlayerTask task, long completedAtMillis)
	{
		this.taskName = task.getTaskName();
		this.initialAmount = task.getInitialAmount();
		this.startedAtMillis = task.getStartMillis();
		this.completedAtMillis = completedAtMillis;
		this.totalMillis = Math.max(0, completedAtMillis - task.getStartMillis());
		this.efficientMillis = Math.min(totalMillis, Math.max(0, task.getEfficientMillis(completedAtMillis)));
		this.manualResetCount = task.getManualResetCount();
	}

	String getTaskName()
	{
		return taskName == null ? "" : taskName;
	}

	int getInitialAmount()
	{
		return initialAmount;
	}

	long getStartedAtMillis()
	{
		return startedAtMillis;
	}

	long getCompletedAtMillis()
	{
		return completedAtMillis;
	}

	long getTotalMillis()
	{
		return Math.max(0, totalMillis);
	}

	long getEfficientMillis()
	{
		return Math.max(0, Math.min(getTotalMillis(), efficientMillis));
	}

	int getManualResetCount()
	{
		return Math.max(0, manualResetCount);
	}

	boolean isValid()
	{
		return !getTaskName().isEmpty() && initialAmount > 0 && completedAtMillis >= startedAtMillis;
	}
}

package com.st3;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.inject.Inject;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
