import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Slayer Task Time Tracker",
	description = "Tracks slayer task completion time, with both overall time and efficient time spent fighting.",
	tags = {"slayer", "tasks", "time", "timer", "tracker"}
)
public class SlayerTaskTimeTrackerPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(SlayerTaskTimeTrackerPlugin.class);
	private static final int BOSS_TASK_ID = 98;
	private static final int MANUAL_TASK_CHECK_SYNC_TICKS = 3;
	private static final Pattern TASK_CHECK_TASK_THEN_COUNT_PATTERN = Pattern.compile(
		"(?i).*(?:assigned|task|hunting).*?(?:kill|slay|defeat|hunt(?:ing)?)\\s+(?:a |an |some |the )?(.+?)[,.;:]?\\s+(?:only\\s+|you have\\s+)?(\\d{1,3}(?:,\\d{3})*)\\s+(?:more\\s+)?(?:to go|left|remaining).*");
	private static final Pattern TASK_CHECK_TASK_IS_COUNT_PATTERN = Pattern.compile(
		"(?i).*(?:slayer task is|task is|assigned to)\\s+(?:a |an |some |the )?(.+?)[,.;:]\\s+(?:only\\s+|you have\\s+)?(\\d{1,3}(?:,\\d{3})*)\\s+(?:more\\s+)?(?:to go|left|remaining).*");
	private static final Pattern TASK_CHECK_COUNT_THEN_TASK_PATTERN = Pattern.compile(
		"(?i).*(?:you (?:have|need to kill)|only)\\s+(\\d{1,3}(?:,\\d{3})*)\\s+(?:more\\s+)?(.+?)\\s+(?:to kill|left|remaining|to go).*");
	private static final Pattern TASK_CHECK_COUNT_ONLY_PATTERN = Pattern.compile(
		"(?i).*(?:only|you have|you've got|there are)\\s+(\\d{1,3}(?:,\\d{3})*)\\s+(?:more\\s+)?to go.*");
	private static final Pattern NO_TASK_CHECK_PATTERN = Pattern.compile(
		"(?i).*(?:no|not).*slayer task.*|.*not currently assigned.*task.*|.*need something new to hunt.*");

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private SlayerTaskTimeTrackerConfig config;

	@Inject
	private SlayerTaskTimeTrackerOverlay overlay;

	@Inject
	private Gson gson;

	@Inject(optional = true)
	private SlayerPluginService slayerPluginService;

	private SlayerTaskTimeTrackerPanel panel;
	private NavigationButton navButton;
	private ActiveSlayerTask activeTask;
	private TaskSnapshot lastObservedTask;
	private List<TaskHistoryEntry> history = new ArrayList<>();
	private int manualTaskCheckSyncTicks;
	private String lastDialogTaskCheckText = "";

	@Provides
	SlayerTaskTimeTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerTaskTimeTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadState();

		panel = injector.getInstance(SlayerTaskTimeTrackerPanel.class);
		updatePanel();

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel.png");
		navButton = NavigationButton.builder()
			.tooltip("Slayer Task Time Tracker")
			.icon(icon)
			.panel(panel)
			.priority(6)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() -> syncTaskFromClient(false));
		}

		log.debug("Slayer Task Time Tracker started");
	}

	@Override
	protected void shutDown()
	{
		stopEfficientSession(System.currentTimeMillis());

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}

		overlayManager.remove(overlay);
		panel = null;
		log.debug("Slayer Task Time Tracker stopped");
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadState();
		updatePanel();

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() -> syncTaskFromClient(false));
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals(SlayerTaskTimeTrackerConfig.GROUP_NAME))
		{
			return;
		}

		if (event.getKey().equals("historyLimit"))
		{
			pruneHistory();
			saveHistory();
			updatePanel();
		}
		else if (event.getKey().equals("timeMode") && panel != null)
		{
			panel.setTimeMode(config.timeMode());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGED_IN:
				clientThread.invokeLater(() -> syncTaskFromClient(false));
				break;
			case LOGGING_IN:
			case HOPPING:
			case LOGIN_SCREEN:
			case CONNECTION_LOST:
				stopEfficientSession(System.currentTimeMillis());
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() == VarPlayerID.SLAYER_COUNT
			|| event.getVarpId() == VarPlayerID.SLAYER_TARGET
			|| event.getVarpId() == VarPlayerID.SLAYER_COUNT_ORIGINAL
			|| event.getVarbitId() == VarbitID.SLAYER_TARGET_BOSSID
			|| event.getVarbitId() == VarbitID.SLAYER_MODIFIER_ID
			|| event.getVarbitId() == VarbitID.SLAYER_MODIFIER_VALUE
			|| event.getVarbitId() == VarbitID.SLAYER_MODIFIER_NEGATIVE
			|| event.getVarbitId() == VarbitID.SLAYER_MODIFIER_ID_STORED
			|| event.getVarbitId() == VarbitID.SLAYER_MODIFIER_VALUE_STORED
			|| event.getVarbitId() == VarbitID.SLAYER_MODIFIER_NEGATIVE_STORED)
		{
			clientThread.invokeLater(() -> syncTaskFromClient(true));
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (activeTask != null && (isPanelActive() || config.showActiveTaskOverlay()))
		{
			updateEfficientSession(System.currentTimeMillis());
			updateActiveTaskPanel();
		}

		syncPendingManualTaskCheck();
		checkSlayerTaskDialogText();
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (activeTask == null || event.getSource() != client.getLocalPlayer())
		{
			return;
		}

		updateEfficientSession(System.currentTimeMillis());
		updateActiveTaskPanel();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		switch (event.getType())
		{
			case GAMEMESSAGE:
			case SPAM:
			case DIALOG:
			case MESBOX:
				handleTaskCheckText(event.getMessage());
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if ((event.getMenuAction() != MenuAction.CC_OP && event.getMenuAction() != MenuAction.CC_OP_LOW_PRIORITY)
			|| !event.getMenuOption().equals("Check"))
		{
			return;
		}

		int itemId = getCheckedItemId(event);
		if (isSlayerTaskCheckItem(itemId))
		{
			manualTaskCheckSyncTicks = MANUAL_TASK_CHECK_SYNC_TICKS;
			log.debug("Manual slayer task check observed");
		}
	}

	void onPanelActivated()
	{
		panel.setTimeMode(config.timeMode());
		updatePanel();
		clientThread.invokeLater(() ->
		{
			updateEfficientSession(System.currentTimeMillis());
			updateActiveTaskPanel();
		});
	}

	void trackCurrentTask()
	{
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}

			TaskSnapshot snapshot = readCurrentTask();
			if (snapshot == null || !snapshot.hasTask())
			{
				lastObservedTask = TaskSnapshot.none();
				updateActiveTaskPanel();
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "No active slayer task found to track.", null);
				return;
			}

			startTask(snapshot, System.currentTimeMillis());
			lastObservedTask = snapshot;
			updatePanel();
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Tracking current slayer task from now.", null);
		});
	}

	private void loadState()
	{
		history = loadHistory();
		activeTask = loadActiveTask();
		lastObservedTask = null;

		if (activeTask != null && activeTask.hasOpenEfficientSession())
		{
			activeTask.clearOpenEfficientSession();
			saveActiveTask();
		}
	}

	private List<TaskHistoryEntry> loadHistory()
	{
		String json = configManager.getRSProfileConfiguration(
			SlayerTaskTimeTrackerConfig.GROUP_NAME,
			SlayerTaskTimeTrackerConfig.HISTORY_KEY);

		if (json == null || json.isEmpty())
		{
			return new ArrayList<>();
		}

		try
		{
			TaskHistoryEntry[] entries = gson.fromJson(json, TaskHistoryEntry[].class);
			if (entries == null)
			{
				return new ArrayList<>();
			}

			List<TaskHistoryEntry> loadedHistory = new ArrayList<>(Arrays.asList(entries));
			loadedHistory.removeIf(entry -> entry == null || !entry.isValid());
			return loadedHistory;
		}
		catch (JsonSyntaxException ex)
		{
			log.debug("Unable to load slayer task time history", ex);
			return new ArrayList<>();
		}
	}

	private ActiveSlayerTask loadActiveTask()
	{
		String json = configManager.getRSProfileConfiguration(
			SlayerTaskTimeTrackerConfig.GROUP_NAME,
			SlayerTaskTimeTrackerConfig.ACTIVE_TASK_KEY);

		if (json == null || json.isEmpty())
		{
			return null;
		}

		try
		{
			ActiveSlayerTask loadedTask = gson.fromJson(json, ActiveSlayerTask.class);
			if (loadedTask == null || !loadedTask.isValid())
			{
				clearActiveTask();
				return null;
			}
			return loadedTask;
		}
		catch (JsonSyntaxException ex)
		{
			log.debug("Unable to load active slayer task time", ex);
			clearActiveTask();
			return null;
		}
	}

	private void syncTaskFromClient(boolean allowNewTaskStart)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		TaskSnapshot snapshot = readCurrentTask();
		if (snapshot == null)
		{
			return;
		}

		long nowMillis = System.currentTimeMillis();
		if (!snapshot.hasTask())
		{
			if (allowNewTaskStart && lastObservedTask != null && lastObservedTask.hasTask())
			{
				applyCheckedNoTask(nowMillis);
			}
			lastObservedTask = snapshot;
			return;
		}

		if (activeTask == null)
		{
			if (allowNewTaskStart && isNewObservedTask(snapshot))
			{
				startTask(snapshot, nowMillis);
				updateActiveTaskPanel();
			}
			lastObservedTask = snapshot;
			return;
		}

		if (!isSameTaskName(activeTask.getTaskName(), snapshot.getTaskName()))
		{
			if (!allowNewTaskStart)
			{
				lastObservedTask = snapshot;
				return;
			}

			log.debug("Replacing slayer task: {} -> {}", activeTask.getTaskName(), snapshot.getTaskName());
			startTask(snapshot, nowMillis);
			lastObservedTask = snapshot;
			updateActiveTaskPanel();
			return;
		}

		if (activeTask.getRemainingAmount() != snapshot.getRemainingAmount()
			|| activeTask.getInitialAmount() != snapshot.getInitialAmount())
		{
			activeTask.updateFrom(snapshot);
			saveActiveTask();
			updateActiveTaskPanel();
		}
		lastObservedTask = snapshot;
	}

	private boolean isNewObservedTask(TaskSnapshot snapshot)
	{
		return lastObservedTask != null && (!lastObservedTask.hasTask() || !snapshot.isSameAssignment(lastObservedTask));
	}

	private TaskSnapshot readCurrentTask()
	{
		int remainingAmount = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		if (remainingAmount <= 0)
		{
			return TaskSnapshot.none();
		}

		int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		int taskDbRow;
		if (taskId == BOSS_TASK_ID)
		{
			List<Integer> bossRows = client.getDBRowsByValue(
				DBTableID.SlayerTaskSublist.ID,
				DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
				0,
				client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));

			if (bossRows.isEmpty())
			{
				return null;
			}

			taskDbRow = (Integer) client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
		}
		else
		{
			List<Integer> taskRows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
			if (taskRows.isEmpty())
			{
				return null;
			}

			taskDbRow = taskRows.get(0);
		}

		String taskName = (String) client.getDBTableField(taskDbRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
		TaskInitialAmount initialAmount = readTaskInitialAmount(remainingAmount);

		return new TaskSnapshot(taskName, initialAmount.getAmount(), remainingAmount, initialAmount.canDecrease());
	}

	private void syncPendingManualTaskCheck()
	{
		if (manualTaskCheckSyncTicks <= 0 || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		TaskSnapshot snapshot = readCurrentTask();
		if (snapshot != null && snapshot.hasTask())
		{
			applyCheckedTask(snapshot);
			manualTaskCheckSyncTicks = 0;
			return;
		}

		manualTaskCheckSyncTicks--;
	}

	private void checkSlayerTaskDialogText()
	{
		Widget dialogText = client.getWidget(InterfaceID.ChatLeft.TEXT);
		if (dialogText == null)
		{
			lastDialogTaskCheckText = "";
			return;
		}

		String text = sanitizeTaskCheckText(dialogText.getText());
		if (text.isEmpty() || text.equals(lastDialogTaskCheckText))
		{
			return;
		}

		lastDialogTaskCheckText = text;
		handleTaskCheckText(text);
	}

	private void handleTaskCheckText(String rawMessage)
	{
		String message = sanitizeTaskCheckText(rawMessage);
		if (message.isEmpty())
		{
			return;
		}

		CheckedTask checkedTask = parseCheckedTask(message);
		if (checkedTask != null)
		{
			applyCheckedTask(checkedTask);
			return;
		}

		if (NO_TASK_CHECK_PATTERN.matcher(message).matches())
		{
			applyCheckedNoTask(System.currentTimeMillis());
		}
	}

	private CheckedTask parseCheckedTask(String message)
	{
		Matcher matcher = TASK_CHECK_TASK_THEN_COUNT_PATTERN.matcher(message);
		if (matcher.matches())
		{
			return checkedTask(matcher.group(1), matcher.group(2));
		}

		matcher = TASK_CHECK_TASK_IS_COUNT_PATTERN.matcher(message);
		if (matcher.matches())
		{
			return checkedTask(matcher.group(1), matcher.group(2));
		}

		matcher = TASK_CHECK_COUNT_THEN_TASK_PATTERN.matcher(message);
		if (matcher.matches())
		{
			String taskName = matcher.group(2);
			if (hasTaskCheckContext(message) || isActiveTaskName(taskName))
			{
				return checkedTask(taskName, matcher.group(1));
			}
		}

		matcher = TASK_CHECK_COUNT_ONLY_PATTERN.matcher(message);
		if (matcher.matches() && (activeTask != null || manualTaskCheckSyncTicks > 0))
		{
			return checkedTask(null, matcher.group(1));
		}

		return null;
	}

	private boolean hasTaskCheckContext(String message)
	{
		String normalizedMessage = message.toLowerCase(Locale.ROOT);
		return normalizedMessage.contains("slayer")
			|| normalizedMessage.contains("task")
			|| normalizedMessage.contains("assigned")
			|| normalizedMessage.contains("hunting")
			|| normalizedMessage.contains("kill")
			|| normalizedMessage.contains("slay")
			|| normalizedMessage.contains("defeat");
	}

	private boolean isActiveTaskName(String taskName)
	{
		return activeTask != null && taskName != null && isSameTaskName(taskName, activeTask.getTaskName());
	}

	private CheckedTask checkedTask(String taskName, String amountText)
	{
		int remainingAmount = parseAmount(amountText);
		if (remainingAmount <= 0)
		{
			return null;
		}

		return new CheckedTask(cleanTaskName(taskName), remainingAmount);
	}

	private void applyCheckedTask(CheckedTask checkedTask)
	{
		TaskSnapshot snapshot = snapshotFromCheckedTask(checkedTask);
		if (snapshot != null && snapshot.hasTask())
		{
			applyCheckedTask(snapshot);
		}
	}

	private TaskSnapshot snapshotFromCheckedTask(CheckedTask checkedTask)
	{
		String taskName = checkedTask.getTaskName();
		int remainingAmount = checkedTask.getRemainingAmount();
		TaskSnapshot currentSnapshot = readCurrentTask();

		if (activeTask != null && (taskName == null || isSameTaskName(taskName, activeTask.getTaskName())))
		{
			taskName = activeTask.getTaskName();
			int initialAmount = Math.max(activeTask.getInitialAmount(), remainingAmount);
			boolean canDecreaseInitialAmount = false;

			if (currentSnapshot != null && currentSnapshot.hasTask()
				&& isSameTaskName(taskName, currentSnapshot.getTaskName())
				&& currentSnapshot.canDecreaseInitialAmount())
			{
				initialAmount = Math.max(currentSnapshot.getInitialAmount(), remainingAmount);
				canDecreaseInitialAmount = true;
			}
			else if (activeTask.getRemainingAmount() == activeTask.getInitialAmount()
				&& remainingAmount <= activeTask.getInitialAmount())
			{
				initialAmount = remainingAmount;
				canDecreaseInitialAmount = true;
			}

			return new TaskSnapshot(taskName, initialAmount, remainingAmount, canDecreaseInitialAmount);
		}

		if (currentSnapshot != null && currentSnapshot.hasTask()
			&& (taskName == null || isSameTaskName(taskName, currentSnapshot.getTaskName())))
		{
			return new TaskSnapshot(
				currentSnapshot.getTaskName(),
				Math.max(currentSnapshot.getInitialAmount(), remainingAmount),
				remainingAmount,
				currentSnapshot.canDecreaseInitialAmount());
		}

		if (taskName == null)
		{
			return null;
		}

		return new TaskSnapshot(taskName, remainingAmount, remainingAmount, true);
	}

	private void applyCheckedTask(TaskSnapshot snapshot)
	{
		long nowMillis = System.currentTimeMillis();
		if (!snapshot.hasTask())
		{
			applyCheckedNoTask(nowMillis);
			return;
		}

		if (activeTask == null)
		{
			startTask(snapshot, nowMillis);
			lastObservedTask = snapshot;
			updateActiveTaskPanel();
			return;
		}

		if (!isSameTaskName(activeTask.getTaskName(), snapshot.getTaskName()))
		{
			log.debug("Replacing slayer task from manual check: {} -> {}", activeTask.getTaskName(), snapshot.getTaskName());
			startTask(snapshot, nowMillis);
			lastObservedTask = snapshot;
			updateActiveTaskPanel();
			return;
		}

		activeTask.updateFrom(snapshot);
		saveActiveTask();
		lastObservedTask = snapshot;
		updateActiveTaskPanel();
	}

	private void applyCheckedNoTask(long nowMillis)
	{
		if (activeTask != null && activeTask.getRemainingAmount() == 1)
		{
			completeActiveTask(nowMillis);
		}
		else if (activeTask != null)
		{
			log.debug("Clearing unfinished slayer task from manual check: {}x {}", activeTask.getRemainingAmount(), activeTask.getTaskName());
			clearActiveTask();
			updateActiveTaskPanel();
		}

		lastObservedTask = TaskSnapshot.none();
	}

	private int getCheckedItemId(MenuOptionClicked event)
	{
		Widget widget = client.getWidget(event.getParam1());
		if (widget == null)
		{
			return -1;
		}

		if (event.getParam0() != -1)
		{
			widget = widget.getChild(event.getParam0());
			if (widget == null)
			{
				return -1;
			}
		}

		int itemId = widget.getItemId();
		for (Widget child : widget.getDynamicChildren())
		{
			if (itemId == -1)
			{
				itemId = child.getItemId();
			}
		}
		return itemId;
	}

	private static boolean isSlayerTaskCheckItem(int itemId)
	{
		if (itemId <= 0)
		{
			return false;
		}

		int mappedItemId = ItemVariationMapping.map(itemId);
		return mappedItemId == ItemID.SLAYER_GEM
			|| mappedItemId == ItemID.SLAYER_ETERNAL_GEM
			|| mappedItemId == ItemID.SLAYER_HELM
			|| mappedItemId == ItemID.SLAYER_HELM_I
			|| isCombatBracelet(itemId)
			|| isCombatBracelet(mappedItemId);
	}

	private static boolean isCombatBracelet(int itemId)
	{
		switch (itemId)
		{
			case ItemID.JEWL_BRACELET_OF_COMBAT:
			case ItemID.JEWL_BRACELET_OF_COMBAT_1:
			case ItemID.JEWL_BRACELET_OF_COMBAT_2:
			case ItemID.JEWL_BRACELET_OF_COMBAT_3:
			case ItemID.JEWL_BRACELET_OF_COMBAT_4:
			case ItemID.JEWL_BRACELET_OF_COMBAT_5:
			case ItemID.JEWL_BRACELET_OF_COMBAT_6:
				return true;
			default:
				return false;
		}
	}

	private static String sanitizeTaskCheckText(String message)
	{
		if (message == null)
		{
			return "";
		}

		String text = Text.sanitizeMultilineText(message)
			.replace('\u00A0', ' ')
			.trim();
		int dialogSeparator = text.indexOf('|');
		if (dialogSeparator >= 0 && dialogSeparator + 1 < text.length())
		{
			text = text.substring(dialogSeparator + 1).trim();
		}

		return text.replaceAll("\\s+", " ");
	}

	private static String cleanTaskName(String taskName)
	{
		if (taskName == null)
		{
			return null;
		}

		String cleanName = taskName
			.replaceAll("(?i)^(?:a|an|some|the)\\s+", "")
			.replaceAll("[.!?]+$", "")
			.replaceAll("\\s+", " ")
			.trim();
		return cleanName.isEmpty() ? null : cleanName;
	}

	private static int parseAmount(String amountText)
	{
		try
		{
			return Integer.parseInt(amountText.replace(",", ""));
		}
		catch (NumberFormatException ex)
		{
			return 0;
		}
	}

	private TaskInitialAmount readTaskInitialAmount(int remainingAmount)
	{
		int originalAmount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		if (originalAmount <= 0)
		{
			return new TaskInitialAmount(remainingAmount, false);
		}

		SlayerModifier quantityModifier = readQuantityModifier();
		if (quantityModifier != null)
		{
			int modifierValue = quantityModifier.isNegative()
				? -quantityModifier.getValue()
				: quantityModifier.getValue();
			int modifiedAmount = originalAmount + modifierValue;
			if (modifiedAmount > 0)
			{
				return new TaskInitialAmount(Math.max(modifiedAmount, remainingAmount), true);
			}
		}

		return new TaskInitialAmount(Math.max(originalAmount, remainingAmount), false);
	}

	private SlayerModifier readQuantityModifier()
	{
		SlayerModifier modifier = readQuantityModifier(
			client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID),
			client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE),
			client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE));
		if (modifier != null)
		{
			return modifier;
		}

		return readQuantityModifier(
			client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID_STORED),
			client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE_STORED),
			client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE_STORED));
	}

	private SlayerModifier readQuantityModifier(int modifierId, int modifierValue, int negative)
	{
		if (modifierValue <= 0 || !isQuantityModifier(modifierId))
		{
			return null;
		}

		return new SlayerModifier(modifierValue, negative > 0);
	}

	private boolean isQuantityModifier(int modifierId)
	{
		if (modifierId <= 0)
		{
			return false;
		}

		if (modifierId == DBTableID.SlayerModifiers.Row.SLAYER_MODIFIER_QUANTITY)
		{
			return true;
		}

		Object[] idField = client.getDBTableField(
			DBTableID.SlayerModifiers.Row.SLAYER_MODIFIER_QUANTITY,
			DBTableID.SlayerModifiers.COL_ID,
			0);
		return idField != null
			&& idField.length > 0
			&& idField[0] instanceof Integer
			&& modifierId == (Integer) idField[0];
	}

	private void startTask(TaskSnapshot snapshot, long nowMillis)
	{
		activeTask = new ActiveSlayerTask(
			snapshot.getTaskName(),
			snapshot.getInitialAmount(),
			snapshot.getRemainingAmount(),
			nowMillis);

		if (isInteractingWithTaskNpc())
		{
			activeTask.startEfficientSession(nowMillis);
		}

		saveActiveTask();
		log.debug("Started slayer task timer: {}x {}", snapshot.getInitialAmount(), snapshot.getTaskName());
	}

	private void completeActiveTask(long nowMillis)
	{
		activeTask.stopEfficientSession(nowMillis);
		TaskHistoryEntry entry = new TaskHistoryEntry(activeTask, nowMillis);
		history.add(0, entry);
		pruneHistory();
		saveHistory();
		clearActiveTask();
		updatePanel();

		String message = "Slayer task complete: "
			+ entry.getTaskName()
			+ " took "
			+ ColorUtil.wrapWithColorTag(DurationFormatter.formatMillis(entry.getTotalMillis()), java.awt.Color.WHITE)
			+ " total ("
			+ DurationFormatter.formatMillis(entry.getEfficientMillis())
			+ " efficient).";
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
	}

	void resetActiveTaskTimer()
	{
		if (activeTask == null)
		{
			return;
		}

		activeTask.resetTimer(System.currentTimeMillis(), isInteractingWithTaskNpc());
		saveActiveTask();
		updateActiveTaskPanel();
	}

	ActiveTaskDisplay getActiveTaskDisplay()
	{
		return activeTask == null ? null : new ActiveTaskDisplay(activeTask, System.currentTimeMillis());
	}

	void toggleActiveTaskOverlay()
	{
		if (activeTask == null)
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					ColorUtil.wrapWithColorTag("You have no active task to display!", java.awt.Color.RED), null);
			}
			return;
		}

		config.setShowActiveTaskOverlay(!config.showActiveTaskOverlay());
	}

	void deleteHistoryEntry(TaskHistoryEntry entry)
	{
		if (entry == null || !history.remove(entry))
		{
			return;
		}

		saveHistory();
		updatePanel();
	}

	private void updateEfficientSession(long nowMillis)
	{
		if (activeTask == null)
		{
			return;
		}

		boolean changed = isInteractingWithTaskNpc()
			? activeTask.startEfficientSession(nowMillis)
			: activeTask.stopEfficientSession(nowMillis);
		if (changed)
		{
			saveActiveTask();
		}
	}

	private void stopEfficientSession(long nowMillis)
	{
		if (activeTask == null)
		{
			return;
		}

		if (activeTask.stopEfficientSession(nowMillis))
		{
			saveActiveTask();
		}
	}

	private boolean isInteractingWithTaskNpc()
	{
		if (activeTask == null)
		{
			return false;
		}

		Player player = client.getLocalPlayer();
		if (player == null || !player.isInteracting())
		{
			return false;
		}

		Actor target = player.getInteracting();
		return target instanceof NPC && isTaskNpc((NPC) target);
	}

	private boolean isTaskNpc(NPC npc)
	{
		if (slayerPluginService != null)
		{
			List<NPC> targets = slayerPluginService.getTargets();
			if (targets != null && targets.contains(npc))
			{
				return true;
			}
		}

		return SlayerTaskTargets.isTarget(npc, activeTask.getTaskName());
	}

	private static boolean isSameTaskName(String firstTaskName, String secondTaskName)
	{
		return SlayerTaskTargets.isSameTaskName(firstTaskName, secondTaskName);
	}

	private void pruneHistory()
	{
		int historyLimit = Math.max(1, config.historyLimit());
		while (history.size() > historyLimit)
		{
			history.remove(history.size() - 1);
		}
	}

	private void saveHistory()
	{
		configManager.setRSProfileConfiguration(
			SlayerTaskTimeTrackerConfig.GROUP_NAME,
			SlayerTaskTimeTrackerConfig.HISTORY_KEY,
			gson.toJson(history));
	}

	private void saveActiveTask()
	{
		if (activeTask == null)
		{
			return;
		}

		configManager.setRSProfileConfiguration(
			SlayerTaskTimeTrackerConfig.GROUP_NAME,
			SlayerTaskTimeTrackerConfig.ACTIVE_TASK_KEY,
			gson.toJson(activeTask));
	}

	private void clearActiveTask()
	{
		activeTask = null;
		configManager.unsetRSProfileConfiguration(
			SlayerTaskTimeTrackerConfig.GROUP_NAME,
			SlayerTaskTimeTrackerConfig.ACTIVE_TASK_KEY);
	}

	private void updatePanel()
	{
		updatePanel(System.currentTimeMillis());
	}

	private void updatePanel(long nowMillis)
	{
		if (!isPanelActive())
		{
			return;
		}

		panel.setHistory(history);
		panel.setActiveTask(activeTask == null ? null : new ActiveTaskDisplay(activeTask, nowMillis));
	}

	private void updateActiveTaskPanel()
	{
		if (isPanelActive())
		{
			panel.setActiveTask(activeTask == null ? null : new ActiveTaskDisplay(activeTask, System.currentTimeMillis()));
		}
	}

	private boolean isPanelActive()
	{
		return panel != null && panel.isActive();
	}

	private static final class CheckedTask
	{
		private final String taskName;
		private final int remainingAmount;

		private CheckedTask(String taskName, int remainingAmount)
		{
			this.taskName = taskName;
			this.remainingAmount = remainingAmount;
		}

		private String getTaskName()
		{
			return taskName;
		}

		private int getRemainingAmount()
		{
			return remainingAmount;
		}
	}

	private static final class TaskInitialAmount
	{
		private final int amount;
		private final boolean canDecrease;

		private TaskInitialAmount(int amount, boolean canDecrease)
		{
			this.amount = amount;
			this.canDecrease = canDecrease;
		}

		private int getAmount()
		{
			return amount;
		}

		private boolean canDecrease()
		{
			return canDecrease;
		}
	}

	private static final class SlayerModifier
	{
		private final int value;
		private final boolean negative;

		private SlayerModifier(int value, boolean negative)
		{
			this.value = value;
			this.negative = negative;
		}

		private int getValue()
		{
			return value;
		}

		private boolean isNegative()
		{
			return negative;
		}
	}
}

package com.st3;

import static net.runelite.api.MenuAction.RUNELITE_OVERLAY;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class SlayerTaskTimeTrackerOverlay extends OverlayPanel
{
	private static final String OVERLAY_NAME = "Slayer Task Time Tracker overlay";
	private static final String SHOW_TOTAL_TIME = "Show total time";
	private static final String HIDE_TOTAL_TIME = "Hide total time";
	private static final String SHOW_EFFICIENT_TIME = "Show efficient time";
	private static final String HIDE_EFFICIENT_TIME = "Hide efficient time";
	private static final int OVERLAY_WIDTH = 170;
	private static final int TASK_NAME_LENGTH = 28;

	private final SlayerTaskTimeTrackerPlugin plugin;
	private final SlayerTaskTimeTrackerConfig config;

	@Inject
	SlayerTaskTimeTrackerOverlay(SlayerTaskTimeTrackerPlugin plugin, SlayerTaskTimeTrackerConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.TOP_LEFT);
		addMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, OVERLAY_NAME);
		addMenuEntry(RUNELITE_OVERLAY, "Reset timer", OVERLAY_NAME, e -> plugin.resetActiveTaskTimer());
		updateMenuEntries();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showActiveTaskOverlay())
		{
			return null;
		}

		ActiveTaskDisplay task = plugin.getActiveTaskDisplay();
		if (task == null)
		{
			return null;
		}

		panelComponent.setPreferredSize(new Dimension(OVERLAY_WIDTH, 0));
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(task.getInitialAmount() + " " + abbreviate(task.getTaskName(), TASK_NAME_LENGTH))
			.color(ColorScheme.BRAND_ORANGE)
			.build());

		if (config.showOverlayTotalTime())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Total")
				.right(DurationFormatter.formatMillis(task.getTotalMillis()))
				.build());
		}

		if (config.showOverlayEfficientTime())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Efficient")
				.right(DurationFormatter.formatMillis(task.getEfficientMillis()))
				.build());
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Remaining")
			.right(task.getRemainingAmount() + "/" + task.getInitialAmount())
			.leftColor(Color.LIGHT_GRAY)
			.rightColor(Color.LIGHT_GRAY)
			.build());

		return super.render(graphics);
	}

	@Override
	public String getName()
	{
		return "SlayerTaskTimeTrackerOverlay";
	}

	private void updateMenuEntries()
	{
		removeMenuEntry(RUNELITE_OVERLAY, SHOW_TOTAL_TIME, OVERLAY_NAME);
		removeMenuEntry(RUNELITE_OVERLAY, HIDE_TOTAL_TIME, OVERLAY_NAME);
		removeMenuEntry(RUNELITE_OVERLAY, SHOW_EFFICIENT_TIME, OVERLAY_NAME);
		removeMenuEntry(RUNELITE_OVERLAY, HIDE_EFFICIENT_TIME, OVERLAY_NAME);

		addMenuEntry(RUNELITE_OVERLAY, config.showOverlayTotalTime() ? HIDE_TOTAL_TIME : SHOW_TOTAL_TIME, OVERLAY_NAME, e ->
		{
			config.setShowOverlayTotalTime(!config.showOverlayTotalTime());
			updateMenuEntries();
		});

		addMenuEntry(RUNELITE_OVERLAY, config.showOverlayEfficientTime() ? HIDE_EFFICIENT_TIME : SHOW_EFFICIENT_TIME, OVERLAY_NAME, e ->
		{
			config.setShowOverlayEfficientTime(!config.showOverlayEfficientTime());
			updateMenuEntries();
		});
	}

	private static String abbreviate(String value, int maxLength)
	{
		if (value.length() <= maxLength)
		{
			return value;
		}

		return value.substring(0, maxLength - 3) + "...";
	}
}

package com.st3;

import java.time.Duration;
import java.util.Locale;

final class DurationFormatter
{
	private DurationFormatter()
	{
	}

	static String formatMillis(long millis)
	{
		Duration duration = Duration.ofMillis(Math.max(0, millis));
		long days = duration.toDays();
		long hours = duration.toHours() % 24;
		long minutes = duration.toMinutes() % 60;
		long seconds = duration.getSeconds() % 60;

		if (days > 0)
		{
			return String.format(Locale.ENGLISH, "%dd %02d:%02d:%02d", days, hours, minutes, seconds);
		}

		return String.format(Locale.ENGLISH, "%02d:%02d:%02d", hours, minutes, seconds);
	}
}

package com.st3;

final class ActiveTaskDisplay
{
	private final String taskName;
	private final int initialAmount;
	private final int remainingAmount;
	private final long totalMillis;
	private final long efficientMillis;
	private final int manualResetCount;

	ActiveTaskDisplay(ActiveSlayerTask task, long nowMillis)
	{
		taskName = task.getTaskName();
		initialAmount = task.getInitialAmount();
		remainingAmount = task.getRemainingAmount();
		totalMillis = Math.max(0, nowMillis - task.getStartMillis());
		efficientMillis = Math.min(totalMillis, Math.max(0, task.getEfficientMillis(nowMillis)));
		manualResetCount = task.getManualResetCount();
	}

	String getTaskName()
	{
		return taskName == null ? "" : taskName;
	}

	int getInitialAmount()
	{
		return initialAmount;
	}

	int getRemainingAmount()
	{
		return remainingAmount;
	}

	long getTotalMillis()
	{
		return totalMillis;
	}

	long getEfficientMillis()
	{
		return efficientMillis;
	}

	int getManualResetCount()
	{
		return manualResetCount;
	}
}

