final class SlayerTaskTargets
{
	private static final Map<String, List<String>> EXTRA_TARGET_NAMES = buildExtraTargetNames();

	private SlayerTaskTargets()
	{
	}

	static boolean isTarget(NPC npc, String taskName)
	{
		NPCComposition composition = npc.getTransformedComposition();
		if (composition == null)
		{
			return false;
		}

		return isTargetName(composition.getName(), taskName, composition.getActions());
	}

	static boolean isTargetName(String npcName, String taskName, String[] actions)
	{
		if (npcName == null || taskName == null || !hasTargetAction(actions))
		{
			return false;
		}

		if (isTaskNameMatch(npcName, taskName))
		{
			return true;
		}

		String normalizedNpcName = normalizeName(npcName);
		List<String> targetNames = targetNamesForTask(taskName);
		if (targetNames == null)
		{
			return false;
		}

		for (String targetName : targetNames)
		{
			if (containsPhrase(normalizedNpcName, targetName))
			{
				return true;
			}
		}

		return false;
	}

	private static List<String> targetNamesForTask(String taskName)
	{
		String normalizedTaskName = normalizeName(taskName);
		List<String> targetNames = EXTRA_TARGET_NAMES.get(normalizedTaskName);
		if (targetNames != null)
		{
			return targetNames;
		}

		String singularTaskName = singularTaskName(removeLeadingThe(normalizedTaskName));
		for (Map.Entry<String, List<String>> entry : EXTRA_TARGET_NAMES.entrySet())
		{
			if (singularTaskName(removeLeadingThe(entry.getKey())).equals(singularTaskName))
			{
				return entry.getValue();
			}
		}

		return null;
	}

	static boolean isSameTaskName(String firstTaskName, String secondTaskName)
	{
		String first = removeLeadingThe(normalizeName(firstTaskName));
		String second = removeLeadingThe(normalizeName(secondTaskName));
		return !first.isEmpty()
			&& !second.isEmpty()
			&& (first.equals(second) || singularTaskName(first).equals(singularTaskName(second)));
	}

	private static boolean isTaskNameMatch(String npcName, String taskName)
	{
		String normalizedNpcName = normalizeName(npcName);
		String normalizedTaskName = normalizeName(taskName);
		if (normalizedNpcName.isEmpty() || normalizedTaskName.isEmpty())
		{
			return false;
		}

		String taskNameWithoutThe = removeLeadingThe(normalizedTaskName);
		return containsPhrase(normalizedNpcName, normalizedTaskName)
			|| containsPhrase(normalizedNpcName, taskNameWithoutThe)
			|| containsPhrase(normalizedNpcName, singularTaskName(taskNameWithoutThe));
	}

	private static boolean hasTargetAction(String[] actions)
	{
		if (actions == null)
		{
			return false;
		}

		for (String action : actions)
		{
			if ("Attack".equals(action) || "Pick".equals(action))
			{
				return true;
			}
		}

		return false;
	}

