		addTargetNames(targetNames, "Zombies", "Undead", "Vorkath", "Zombie pirate", "Zogre", "Zogres");
		return Collections.unmodifiableMap(targetNames);
	}

	private static void addTargetNames(Map<String, List<String>> tasks, String taskName, String... targetNames)
	{
		List<String> normalizedTargetNames = new ArrayList<>(targetNames.length);
		for (String targetName : targetNames)
		{
			normalizedTargetNames.add(normalizeName(targetName));
		}

		tasks.put(normalizeName(taskName), Collections.unmodifiableList(normalizedTargetNames));
	}

	private static String normalizeName(String name)
	{
		if (name == null)
		{
			return "";
		}

		return name
			.replace('\u00A0', ' ')
			.toLowerCase(Locale.ROOT)
			.replaceAll("[^a-z0-9']+", " ")
			.trim();
	}

	private static String removeLeadingThe(String name)
	{
		return name.startsWith("the ") ? name.substring(4) : name;
	}

	private static String singularTaskName(String name)
	{
		if ((name.endsWith("bies") || name.endsWith("cies") || name.endsWith("sies")) && name.length() > 4)
		{
			return name.substring(0, name.length() - 1);
		}

		if (name.endsWith("ies") && name.length() > 3)
		{
			return name.substring(0, name.length() - 3) + "y";
		}

		if (name.endsWith("ves") && name.length() > 3)
		{
			return name.substring(0, name.length() - 3) + "f";
		}

		if (name.endsWith("s") && !name.endsWith("ss") && name.length() > 1)
		{
			return name.substring(0, name.length() - 1);
		}

		return name;
	}

	private static boolean containsPhrase(String value, String phrase)
	{
		return !phrase.isEmpty() && (" " + value + " ").contains(" " + phrase + " ");
	}
}

