	private void selectModeButton()
	{
		totalTimeButton.setSelected(timeMode == TaskTimeMode.TOTAL);
		efficientButton.setSelected(timeMode == TaskTimeMode.EFFICIENT);
	}

	private void rebuildActiveTask()
	{
		activeTaskContainer.removeAll();

		if (activeTask == null)
		{
			activeTaskContainer.add(buildEmptyActiveTaskPanel(), BorderLayout.CENTER);
			activeTaskContainer.setPreferredSize(new Dimension(0, 52));
			activeTaskContainer.setMaximumSize(new Dimension(Integer.MAX_VALUE, 52));
			refreshActionButtons();
		}
		else
		{
			activeTaskContainer.add(buildActiveTaskPanel(activeTask), BorderLayout.CENTER);
			activeTaskContainer.setPreferredSize(new Dimension(0, 86));
			activeTaskContainer.setMaximumSize(new Dimension(Integer.MAX_VALUE, 86));
			refreshActionButtons();
		}

		activeTaskContainer.revalidate();
		activeTaskContainer.repaint();
	}

	private JPanel buildCompletedTotalsPanel()
