		completedTotalsPanel.setBorder(new CompoundBorder(
			BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.DARKER_GRAY_COLOR),
			new EmptyBorder(6, 0, 0, 0)));
		completedTotalsPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

		completedTotalsPanel.add(createSectionHeader("Completed totals"));
		completedTotalsPanel.add(buildCompletedTotalRow("Total", completedTotalTimeValue));
		completedTotalsPanel.add(Box.createVerticalStrut(2));
		completedTotalsPanel.add(buildCompletedTotalRow("Efficient", completedEfficientTimeValue));

		return completedTotalsPanel;
	}

	private JPanel buildCompletedTotalRow(String labelText, JLabel valueLabel)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(2, 8, 2, 8));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel label = new JLabel(labelText);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());
		row.add(label, BorderLayout.WEST);

		valueLabel.setForeground(ColorScheme.BRAND_ORANGE);
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		valueLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		row.add(valueLabel, BorderLayout.EAST);

		return row;
	}

	private void rebuildCompletedTotals()
	{
		long totalMillis = 0;
		long efficientMillis = 0;
		for (TaskHistoryEntry entry : history)
		{
			totalMillis += entry.getTotalMillis();
			efficientMillis += entry.getEfficientMillis();
		}

		completedTotalTimeValue.setText(DurationFormatter.formatMillis(totalMillis));
		completedEfficientTimeValue.setText(DurationFormatter.formatMillis(efficientMillis));
		setTooltipRecursively(completedTotalsPanel, activeTask == null ? null : COMPLETED_TOTALS_TOOLTIP);
		completedTotalsPanel.revalidate();
		completedTotalsPanel.repaint();
	}

	private void setTooltipRecursively(Component component, String tooltip)
	{
		if (component instanceof JComponent)
		{
			((JComponent) component).setToolTipText(tooltip);
		}

		if (component instanceof JPanel)
		{
			for (Component child : ((JPanel) component).getComponents())
			{
				setTooltipRecursively(child, tooltip);
			}
		}
	}

	private JPanel buildEmptyActiveTaskPanel()
