	private void refreshActionButtons()
	{
		trackNowButton.setEnabled(activeTask == null);
	}

	private JPanel buildActiveTaskPanel(ActiveTaskDisplay task)
	{
		String title = task.getInitialAmount() + " " + abbreviate(task.getTaskName(), NAME_LENGTH);
		String details = task.getRemainingAmount() + " remaining / " + task.getInitialAmount() + " assigned";
		JPanel panel = buildTimerRow(title, durationText(task), details, ColorScheme.BRAND_ORANGE,
			ColorScheme.DARKER_GRAY_COLOR, buildResetButton(), buildActiveModeControls(), 86);
		panel.setToolTipText(buildTooltip(task));
		return panel;
	}

	private void rebuildHistory()
	{
		historyContainer.removeAll();

		if (history.isEmpty())
		{
			historyContainer.add(buildInfoPanel("No completed tasks tracked."));
			revalidate();
			repaint();
			return;
		}

		List<TaskHistoryEntry> sortedHistory = new ArrayList<>(history);
		sortedHistory.sort(Comparator.comparingLong(TaskHistoryEntry::getCompletedAtMillis).reversed());

		for (TaskHistoryEntry entry : sortedHistory)
		{
			historyContainer.add(buildTaskRow(entry));
			historyContainer.add(Box.createVerticalStrut(4));
		}

		revalidate();
		repaint();
	}

	private JPanel buildTaskRow(TaskHistoryEntry entry)
	{
		String title = entry.getInitialAmount() + " " + abbreviate(entry.getTaskName(), NAME_LENGTH);
		Color background = entry.getManualResetCount() > 0 ? RESET_ROW_COLOR : ColorScheme.DARKER_GRAY_COLOR;
		JPanel panel = buildTimerRow(title, DurationFormatter.formatMillis(timeMode.durationMillis(entry)),
			entry.getInitialAmount() + " assigned", ColorScheme.LIGHT_GRAY_COLOR.darker(), background, buildDeleteButton(entry));
		panel.setToolTipText(buildTooltip(entry));
		return panel;
	}

	private JPanel buildTimerRow(String title, String duration, String details, Color durationColor, Color background,
		JButton titleButton)
	{
		return buildTimerRow(title, duration, details, durationColor, background, titleButton, null, 70);
	}

	private JPanel buildTimerRow(String title, String duration, String details, Color durationColor, Color background,
		JButton titleButton, JComponent detailsAccessory, int rowHeight)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBorder(new EmptyBorder(3, 0, 0, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setPreferredSize(new Dimension(0, rowHeight));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, rowHeight));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel titlePanel = new JPanel(new BorderLayout());
		titlePanel.setBackground(background);
		titlePanel.setBorder(ROW_TITLE_BORDER);

		JLabel titleLabel = new JLabel(title);
		titleLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		titleLabel.setFont(FontManager.getRunescapeSmallFont());
		titleLabel.setBorder(new EmptyBorder(0, 8, 0, 8));
		titleLabel.setPreferredSize(new Dimension(0, 22));
		titlePanel.add(titleLabel, BorderLayout.CENTER);
		if (titleButton != null)
		{
			titlePanel.add(titleButton, BorderLayout.EAST);
		}

		JPanel body = new JPanel(new BorderLayout());
		body.setBorder(new EmptyBorder(5, 8, 5, 8));
		body.setBackground(background);

		JLabel durationLabel = new JLabel(duration);
		durationLabel.setForeground(durationColor);
		durationLabel.setFont(FontManager.getRunescapeSmallFont());
		durationLabel.setHorizontalAlignment(SwingConstants.CENTER);
		body.add(durationLabel, BorderLayout.CENTER);

		JLabel detailLabel = new JLabel(details);
		detailLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker());
		detailLabel.setFont(FontManager.getRunescapeSmallFont());

		JPanel detailPanel = new JPanel(new BorderLayout());
		detailPanel.setOpaque(false);
		detailPanel.add(detailLabel, BorderLayout.CENTER);
		if (detailsAccessory != null)
		{
			detailPanel.add(detailsAccessory, BorderLayout.EAST);
		}
		body.add(detailPanel, BorderLayout.SOUTH);

		row.add(titlePanel, BorderLayout.NORTH);
		row.add(body, BorderLayout.CENTER);
		return row;
	}

	private JPanel buildActiveModeControls()
	{
		JPanel controls = new JPanel(new GridLayout(1, 2, 2, 0));
		controls.setOpaque(false);
		controls.setPreferredSize(new Dimension(72, 16));

		ButtonGroup group = new ButtonGroup();
