	private JButton buildDeleteButton(TaskHistoryEntry entry)
	{
		JButton button = new JButton("X");
		SwingUtil.removeButtonDecorations(button);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		button.setPreferredSize(new Dimension(18, 18));
		button.setToolTipText("Delete this task record.");
		button.addActionListener(event ->
		{
			int result = JOptionPane.showConfirmDialog(
				this,
				"Delete this task record?",
				"Delete Task Record",
				JOptionPane.YES_NO_OPTION,
				JOptionPane.WARNING_MESSAGE);
			if (result == JOptionPane.YES_OPTION)
			{
				plugin.deleteHistoryEntry(entry);
			}
		});
		return button;
	}

	private JPanel buildInfoPanel(String text)
	{
		JPanel panel = new JPanel(new BorderLayout());
		panel.setBorder(new EmptyBorder(5, 8, 5, 8));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));

		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker());
		label.setFont(FontManager.getRunescapeSmallFont());
		panel.add(label, BorderLayout.CENTER);

		return panel;
	}

	private String buildTooltip(ActiveTaskDisplay task)
	{
		return "<html>"
			+ task.getTaskName()
			+ "<br>Total: " + DurationFormatter.formatMillis(task.getTotalMillis())
			+ "<br>Efficient: " + DurationFormatter.formatMillis(task.getEfficientMillis())
			+ resetTooltipLine(task.getManualResetCount())
			+ "</html>";
	}

	private String buildTooltip(TaskHistoryEntry entry)
	{
		return "<html>"
			+ entry.getTaskName()
			+ "<br>Total: " + DurationFormatter.formatMillis(entry.getTotalMillis())
			+ "<br>Efficient: " + DurationFormatter.formatMillis(entry.getEfficientMillis())
			+ resetTooltipLine(entry.getManualResetCount())
			+ "</html>";
	}

	private String resetTooltipLine(int resetCount)
	{
		if (resetCount <= 0)
		{
			return "";
		}

		return "<br>This task timer was manually reset " + resetCount + " time(s)";
	}

	private String durationText(ActiveTaskDisplay task)
	{
		return DurationFormatter.formatMillis(activeTimeMode == TaskTimeMode.TOTAL ? task.getTotalMillis() : task.getEfficientMillis());
	}

	private static String abbreviate(String value, int maxLength)
	{
		if (value.length() <= maxLength)
		{
			return value;
		}

		return value.substring(0, maxLength - 3) + "...";
	}
}

package com.st3;

final class TaskSnapshot
{
	private final boolean hasTask;
	private final String taskName;
	private final int initialAmount;
	private final int remainingAmount;
	private final boolean initialAmountCanDecrease;

	private TaskSnapshot()
	{
		this.hasTask = false;
		this.taskName = "";
		this.initialAmount = 0;
		this.remainingAmount = 0;
		this.initialAmountCanDecrease = false;
	}

	TaskSnapshot(String taskName, int initialAmount, int remainingAmount)
	{
		this(taskName, initialAmount, remainingAmount, false);
	}

	TaskSnapshot(String taskName, int initialAmount, int remainingAmount, boolean initialAmountCanDecrease)
	{
		this.hasTask = true;
		this.taskName = taskName;
		this.initialAmount = initialAmount;
		this.remainingAmount = remainingAmount;
		this.initialAmountCanDecrease = initialAmountCanDecrease;
	}

	static TaskSnapshot none()
	{
		return new TaskSnapshot();
	}

	boolean hasTask()
	{
		return hasTask;
	}

	String getTaskName()
	{
		return taskName;
	}

	int getInitialAmount()
	{
		return initialAmount;
	}

	int getRemainingAmount()
	{
		return remainingAmount;
	}

	boolean canDecreaseInitialAmount()
	{
		return initialAmountCanDecrease;
	}

	boolean isSameAssignment(TaskSnapshot other)
	{
		return other != null
			&& hasTask == other.hasTask
			&& (!hasTask || taskName.equals(other.taskName));
	}
}

package com.st3;

final class ActiveSlayerTask
{
	private String taskName;
	private int initialAmount;
	private int remainingAmount;
	private long startMillis;
	private long efficientMillis;
	private long efficientStartMillis;
	private int manualResetCount;

	@SuppressWarnings("unused")
	private ActiveSlayerTask()
	{
	}

	ActiveSlayerTask(String taskName, int initialAmount, int remainingAmount, long startMillis)
	{
		this.taskName = taskName;
		this.initialAmount = initialAmount;
		this.remainingAmount = remainingAmount;
		this.startMillis = startMillis;
	}

	String getTaskName()
	{
		return taskName;
	}

	int getInitialAmount()
	{
		return initialAmount;
	}

	int getRemainingAmount()
	{
		return remainingAmount;
	}

	long getStartMillis()
	{
		return startMillis;
	}

	int getManualResetCount()
	{
		return manualResetCount;
	}

	void updateFrom(TaskSnapshot snapshot)
	{
		remainingAmount = snapshot.getRemainingAmount();

		if (snapshot.canDecreaseInitialAmount() && snapshot.getInitialAmount() >= remainingAmount)
		{
			initialAmount = snapshot.getInitialAmount();
		}
		else if (snapshot.getInitialAmount() > initialAmount)
		{
			initialAmount = snapshot.getInitialAmount();
		}
	}

	boolean isSameAssignment(TaskSnapshot snapshot)
	{
		return taskName.equals(snapshot.getTaskName());
	}

	boolean hasOpenEfficientSession()
	{
		return efficientStartMillis > 0;
	}

	boolean startEfficientSession(long nowMillis)
	{
		if (efficientStartMillis == 0)
		{
			efficientStartMillis = nowMillis;
			return true;
		}

		return false;
	}

	boolean stopEfficientSession(long nowMillis)
	{
		if (efficientStartMillis == 0)
		{
			return false;
		}

		efficientMillis += Math.max(0, nowMillis - efficientStartMillis);
		efficientStartMillis = 0;
		return true;
	}

	void clearOpenEfficientSession()
	{
		efficientStartMillis = 0;
	}

	void resetTimer(long nowMillis, boolean efficient)
	{
		startMillis = nowMillis;
		efficientMillis = 0;
		efficientStartMillis = efficient ? nowMillis : 0;
		manualResetCount++;
	}

	long getEfficientMillis(long nowMillis)
	{
		if (efficientStartMillis == 0)
		{
			return efficientMillis;
		}

		return efficientMillis + Math.max(0, nowMillis - efficientStartMillis);
	}

	boolean isValid()
	{
		return taskName != null && !taskName.isEmpty() && initialAmount > 0 && startMillis > 0;
	}
}

