package com.st3;

public enum TaskTimeMode
{
	TOTAL("Total time")
	{
		@Override
		long durationMillis(TaskHistoryEntry entry)
		{
			return entry.getTotalMillis();
		}
	},
	EFFICIENT("Efficient")
	{
		@Override
		long durationMillis(TaskHistoryEntry entry)
		{
			return entry.getEfficientMillis();
		}
	};

	private final String displayName;

	TaskTimeMode(String displayName)
	{
		this.displayName = displayName;
	}

	abstract long durationMillis(TaskHistoryEntry entry);

	@Override
	public String toString()
	{
		return displayName;
	}
}
